<?php
require_once __DIR__.'/includes/auth.php';
$message='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!hash_equals((string)($_SESSION['delegate_csrf']??''),(string)($_POST['csrf_token']??''))) $message='<div class="alert alert-danger">Your session expired. Please try again.</div>';
    else {
        $name=trim((string)($_POST['emergency_contact_name']??''));$phone=trim((string)($_POST['emergency_contact_phone']??''));$relationship=trim((string)($_POST['emergency_contact_relationship']??''));
        if($name===''||$relationship===''||!preg_match('/^[+0-9()\-\s]{8,30}$/',$phone)) $message='<div class="alert alert-warning">Enter a contact name, relationship and a valid phone number.</div>';
        elseif(mb_strlen($name)>150||mb_strlen($relationship)>100) $message='<div class="alert alert-warning">The emergency contact details are too long.</div>';
        else {$pdo->prepare('UPDATE athletes SET emergency_contact_name=?,emergency_contact_phone=?,emergency_contact_relationship=? WHERE id=?')->execute([$name,$phone,$relationship,$delegateId]);recordActivity($pdo,'delegate_emergency_contact_updated','athlete',$delegateId,'Delegate updated emergency contact details.',[],null,'delegate','delegate-'.$delegateId);$delegate['emergency_contact_name']=$name;$delegate['emergency_contact_phone']=$phone;$delegate['emergency_contact_relationship']=$relationship;$message='<div class="alert alert-success">Emergency contact updated successfully.</div>';}
    }
}
function dv($value,string $fallback='Not provided'):string{return htmlspecialchars(trim((string)$value)!==''?(string)$value:$fallback);}
function fv($number,$datetime):string{return trim((string)$datetime)===''?'Not assigned':dv($number).' · '.htmlspecialchars(date('d M Y, H:i',strtotime($datetime)));}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Details - CAMS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.1/font/bootstrap-icons.css"></head><body class="bg-light"><nav class="navbar navbar-dark bg-primary"><div class="container"><a class="navbar-brand" href="dashboard.php"><i class="bi bi-person-vcard me-2"></i>CAMS Delegate</a><div class="d-flex gap-2"><a class="btn btn-sm btn-light" href="claims.php"><i class="bi bi-receipt me-1"></i>Expense Claims</a><a class="btn btn-sm btn-outline-light" href="logout.php">Logout</a></div></div></nav><main class="container py-4" style="max-width:980px"><div class="mb-4"><h1 class="h3 mb-1">Welcome, <?php echo dv($delegate['first_name']);?></h1><p class="text-muted mb-0">Your registered event information is read-only. Contact your country manager if it needs correction.</p></div><?php echo $message;?><div class="row g-4"><div class="col-lg-7"><div class="card border-0 shadow-sm h-100"><div class="card-body"><h2 class="h5 border-bottom pb-3 mb-3">My Details</h2><dl class="row mb-0"><dt class="col-sm-5">Full name</dt><dd class="col-sm-7"><?php echo dv($delegate['first_name'].' '.$delegate['last_name']);?></dd><dt class="col-sm-5">Delegation</dt><dd class="col-sm-7"><?php echo dv($delegate['country_name'],$delegate['delegation_username']);?></dd><dt class="col-sm-5">Participant type</dt><dd class="col-sm-7"><?php echo dv(ucfirst($delegate['participant_type']));?><?php echo $delegate['participant_subtype_name']?' · '.dv($delegate['participant_subtype_name']):'';?></dd><dt class="col-sm-5">Gender</dt><dd class="col-sm-7"><?php echo dv($delegate['gender']);?></dd><dt class="col-sm-5">T-shirt size</dt><dd class="col-sm-7"><?php echo dv($delegate['tshirt_size'],'Not assigned');?></dd><dt class="col-sm-5">Meal preference</dt><dd class="col-sm-7"><?php echo dv(str_replace('_',' ',ucfirst((string)$delegate['meal_preference'])),'Not assigned');?></dd><dt class="col-sm-5">Allergies</dt><dd class="col-sm-7"><?php echo dv($delegate['allergy_details'],'None provided');?></dd><dt class="col-sm-5">Hotel / room</dt><dd class="col-sm-7"><?php echo dv($delegate['hotel_name'],'Not assigned');?><?php echo $delegate['room_number']?' · Room '.dv($delegate['room_number']):'';?></dd><dt class="col-sm-5">Arrival</dt><dd class="col-sm-7"><?php echo fv($delegate['arrival_flight'],$delegate['arrival_datetime']);?></dd><dt class="col-sm-5">Departure</dt><dd class="col-sm-7"><?php echo fv($delegate['departure_flight'],$delegate['departure_datetime']);?></dd></dl></div></div></div><div class="col-lg-5"><div class="card border-0 shadow-sm"><div class="card-body"><h2 class="h5 border-bottom pb-3 mb-3">Emergency Contact</h2><form method="post"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars($_SESSION['delegate_csrf']);?>"><label class="form-label">Contact name</label><input class="form-control mb-3" name="emergency_contact_name" maxlength="150" value="<?php echo dv($delegate['emergency_contact_name'],'');?>" required><label class="form-label">Phone number</label><input class="form-control mb-3" type="tel" name="emergency_contact_phone" maxlength="30" value="<?php echo dv($delegate['emergency_contact_phone'],'');?>" required><label class="form-label">Relationship</label><input class="form-control mb-3" name="emergency_contact_relationship" maxlength="100" value="<?php echo dv($delegate['emergency_contact_relationship'],'');?>" required><button class="btn btn-primary w-100" type="submit"><i class="bi bi-save me-1"></i>Update Emergency Contact</button></form></div></div></div></div></main></body></html>
